<?php
require __DIR__.'/ui.php';role(['admin','gerente','producao']);$p=db();
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$s=$p->prepare("SELECT * FROM products WHERE id=?");$s->execute([$_POST['product_id']]);$pr=$s->fetch();$q=floatval($_POST['qty']);$cost=$q*$pr['cost'];$p->prepare("INSERT INTO losses(product_id,qty,cost,reason,loss_date,user_id)VALUES(?,?,?,?,?,?)")->execute([$pr['id'],$q,$cost,$_POST['reason'],$_POST['loss_date'],current_user()['id']]);$p->prepare("UPDATE products SET stock=MAX(0,stock-?) WHERE id=?")->execute([$q,$pr['id']]);go('losses.php');}
$products=$p->query("SELECT id,name FROM products ORDER BY name")->fetchAll();$rows=$p->query("SELECT l.*,p.name FROM losses l LEFT JOIN products p ON p.id=l.product_id ORDER BY l.id DESC")->fetchAll();page_head('Perdas e desperdícios');?>
<div class="grid g2"><div class="card"><h2>Registrar perda</h2><form method="post"><?=csrf_field()?><label>Produto</label><select name="product_id"><?php foreach($products as $x):?><option value="<?=$x['id']?>"><?=e($x['name'])?></option><?php endforeach;?></select><label>Quantidade</label><input type="number" step=".01" name="qty" required><label>Motivo</label><select name="reason"><option>Flor murcha</option><option>Produto vencido</option><option>Quebra/avaria</option><option>Erro de personalização</option><option>Uso interno</option><option>Outro</option></select><label>Data</label><input type="date" name="loss_date" value="<?=date('Y-m-d')?>"><button class="primary">Registrar</button></form></div><div class="card kpi"><span>Valor perdido</span><strong><?=money(array_sum(array_column($rows,'cost')))?></strong></div></div>
<div class="card"><div class="table"><table><tr><th>Data</th><th>Produto</th><th>Qtd.</th><th>Motivo</th><th>Custo</th></tr><?php foreach($rows as $x):?><tr><td><?=e($x['loss_date'])?></td><td><?=e($x['name'])?></td><td><?=$x['qty']?></td><td><?=e($x['reason'])?></td><td><?=money($x['cost'])?></td></tr><?php endforeach;?></table></div></div><?php page_foot();?>